-- calc_employees_name
-- Field: Employees.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_employees_name(p_employee_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(first_name, '') FROM employees WHERE employee_id = p_employee_id), ' ', (SELECT NULLIF(last_name, '') FROM employees WHERE employee_id = p_employee_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_employee_name
-- Field: ExpenseReports.EmployeeName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Name from related Employees

CREATE OR REPLACE FUNCTION calc_expense_reports_employee_name(p_expense_report_id TEXT)
RETURNS TEXT AS $$
  SELECT calc_employees_name((SELECT employee FROM expense_reports WHERE expense_report_id = p_expense_report_id));
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_employee_budget_limit
-- Field: ExpenseReports.EmployeeBudgetLimit
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: BudgetLimit from related Employees

CREATE OR REPLACE FUNCTION calc_expense_reports_employee_budget_limit(p_expense_report_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT budget_limit::numeric FROM employees WHERE employee_id = (SELECT employee FROM expense_reports WHERE expense_report_id = p_expense_report_id));
$$ LANGUAGE sql STABLE;

-- get_employees_first_name
-- Helper function: Get FirstName from Employees by EmployeeId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_employees_first_name(p_employee_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT first_name FROM employees WHERE employee_id = p_employee_id);
$$ LANGUAGE sql STABLE;

-- get_employees_last_name
-- Helper function: Get LastName from Employees by EmployeeId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_employees_last_name(p_employee_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT last_name FROM employees WHERE employee_id = p_employee_id);
$$ LANGUAGE sql STABLE;

-- get_employees_email_address
-- Helper function: Get EmailAddress from Employees by EmployeeId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_employees_email_address(p_employee_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT email_address FROM employees WHERE employee_id = p_employee_id);
$$ LANGUAGE sql STABLE;

-- get_employees_role
-- Helper function: Get Role from Employees by EmployeeId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_employees_role(p_employee_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT role FROM employees WHERE employee_id = p_employee_id);
$$ LANGUAGE sql STABLE;

-- get_employees_budget_limit
-- Helper function: Get BudgetLimit from Employees by EmployeeId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_employees_budget_limit(p_employee_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT budget_limit FROM employees WHERE employee_id = p_employee_id);
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_total_amount
-- Field: ExpenseReports.TotalAmount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_expense_reports_total_amount(p_expense_report_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((amount)::numeric), 0) FROM expense_items WHERE expense_report = p_expense_report_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_is_over_budget
-- Field: ExpenseReports.IsOverBudget
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expense_reports_is_over_budget(p_expense_report_id TEXT)
RETURNS BOOLEAN AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_expense_reports_employee_budget_limit(p_expense_report_id) AS val) SELECT (CASE WHEN (((SELECT val FROM __erb_dedup_v1))::NUMERIC > 0 AND calc_expense_reports_total_amount(p_expense_report_id) > (SELECT val FROM __erb_dedup_v1)) THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_is_approved
-- Field: ExpenseReports.IsApproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expense_reports_is_approved(p_expense_report_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (SELECT NULLIF(approval_status, '') FROM expense_reports WHERE expense_report_id = p_expense_report_id) = 'approved' THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_expense_reports_requires_escalation
-- Field: ExpenseReports.RequiresEscalation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_expense_reports_requires_escalation(p_expense_report_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN (calc_expense_reports_is_over_budget(p_expense_report_id) = TRUE AND calc_expense_reports_is_approved(p_expense_report_id) = FALSE) THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

-- get_expense_reports_name
-- Helper function: Get Name from ExpenseReports by ExpenseReportId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_expense_reports_name(p_expense_report_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT name FROM expense_reports WHERE expense_report_id = p_expense_report_id);
$$ LANGUAGE sql STABLE;

-- get_expense_reports_approval_status
-- Helper function: Get ApprovalStatus from ExpenseReports by ExpenseReportId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_expense_reports_approval_status(p_expense_report_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT approval_status FROM expense_reports WHERE expense_report_id = p_expense_report_id);
$$ LANGUAGE sql STABLE;

